// Icons for Keel's board and card buttons (generated by scripts/make-icons.mjs).
const url = (file) => new URL(`../../img/icons/${file}`, import.meta.url).href;

/** Board button icon: dark for light board headers, light for dark ones. */
export function boardIcon(name) {
  return { dark: url(`${name}-dark.svg`), light: url(`${name}-light.svg`) };
}

/** Card button icon (Trello shows these in grey). */
export function cardIcon(name) {
  return url(`${name}-gray.svg`);
}
